// Title: Cubie & the Treasure Boxes
var GAME = (function () {
  var CONFIG = {
    W: 360, H: 560,
    playerSpeed: 2.7,
    playerHp: 5,
    fireEvery: 20,
    bulletSpeed: 6.5,
    bulletDamage: 1,
    range: 245,
    enemySpeed: 0.85,
    potionChance: 0.35,
    spikeGap: 54,
    bossHp: 30,
    bossFireEvery: 50,
    rooms: [
      { name: 'Bubble Meadow', enemies: 3 },
      { name: 'Candy Thorns', enemies: 4, spikes: true },
      { name: 'Rainbow Vault', enemies: 2, boss: true }
    ]
  };

  function rng(seed) {
    var s = seed >>> 0 || 1;
    return function () { s ^= s << 13; s >>>= 0; s ^= s >> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; };
  }

  function ensure(st) {
    if (!st.events) st.events = [];
    if (!st.enemies) st.enemies = [];
    if (!st.bullets) st.bullets = [];
    if (!st.shots) st.shots = [];
    if (!st.pickups) st.pickups = [];
    if (!st.boxes) st.boxes = [];
    if (!st.particles) st.particles = [];
    if (st.player && !st.player.inventory) st.player.inventory = [];
  }

  function create(seed) {
    var st = {
      rand: rng(seed || 1), frame: 0, room: 0, score: 0, coins: 0, over: false, won: false,
      player: { x: CONFIG.W / 2, y: CONFIG.H - 50, r: 11, hp: CONFIG.playerHp, cool: 0, hurt: 0, inventory: [], lookX: 0, lookY: 0 },
      enemies: [], bullets: [], shots: [], pickups: [], boxes: [], particles: [], spikes: null, events: []
    };
    enterRoom(st, 0);
    return st;
  }

  function enterRoom(st, i) {
    ensure(st);
    st.room = i;
    var room = CONFIG.rooms[i];
    st.player.x = CONFIG.W / 2; st.player.y = CONFIG.H - 50; st.player.cool = 0;
    st.enemies = []; st.bullets = []; st.shots = []; st.pickups = []; st.boxes = []; st.particles = [];
    for (var k = 0; k < room.enemies; k++) {
      st.enemies.push({ x: 34 + st.rand() * (CONFIG.W - 68), y: 60 + st.rand() * (CONFIG.H - 240), r: 11, hp: 3, kind: 'jelly' });
    }
    if (room.boss) st.enemies.push({ x: CONFIG.W / 2, y: 118, r: 30, hp: CONFIG.bossHp, max: CONFIG.bossHp, kind: 'boss', cool: 0 });
    st.spikes = null;
    if (room.spikes) {
      var gx = 62 + st.rand() * (CONFIG.W - 124);
      st.spikes = { y: CONFIG.H / 2 - 20, h: 40, gapX: gx, gapW: CONFIG.spikeGap };
    }
    var boxCount = room.boss ? 3 : 2;
    for (k = 0; k < boxCount; k++) {
      var bx = 42 + st.rand() * (CONFIG.W - 84);
      var by = 74 + st.rand() * (CONFIG.H - 230);
      if (st.spikes && by > st.spikes.y - 30 && by < st.spikes.y + st.spikes.h + 30) by = st.spikes.y - 58;
      if (Math.abs(bx - CONFIG.W / 2) < 46 && by > CONFIG.H - 150) by = CONFIG.H - 190;
