      if (e.kind === 'boss') {
        e.cool = (e.cool || 0) + 1;
        if (e.cool >= CONFIG.bossFireEvery) {
          e.cool = 0;
          for (var a = 0; a < 8; a++) st.bullets.push({ x: e.x, y: e.y, vx: Math.cos(a * Math.PI / 4) * 2.2, vy: Math.sin(a * Math.PI / 4) * 2.2 });
        }
