      ctx.fillStyle = '#e09f3e'; ctx.fillRect(bx - 13, by - 13, 26, 8);
      ctx.fillStyle = '#ffd93d'; ctx.fillRect(bx - 3, by - 13, 6, 22);
      ctx.fillStyle = '#fff3a0'; ctx.beginPath(); ctx.arc(bx, by - 1, 4, 0, 7); ctx.fill();
