      ctx.beginPath(); ctx.arc(e.x + r * 0.35, e.y - 2, 4, 0, 7); ctx.fill();
      ctx.fillStyle = '#2b2033';
      ctx.beginPath(); ctx.arc(e.x - r * 0.35, e.y - 1, 2, 0, 7); ctx.fill();
      ctx.beginPath(); ctx.arc(e.x + r * 0.35, e.y - 1, 2, 0, 7); ctx.fill();
